## ✅ 풀이 방법
기존에 풀었었던 스택을 이용해서 괄호의 짝을 찾아주는 방식을 이용.
채점했을 때 하나의 케이스만 실패했었는데, flg 와 함께 stack의 길이가 0일때만 answer++ 해줘야하므로 그 조건까지 if문에 넣어주니 정답
## 📜 최종 소스코드

```js
function solution(s) {
  let answer = 0;
  const arr = [...s];
  let stack = [];
  let tmp = "";
  let flg = true;
  for (let i = 0; i < arr.length; i++) {
    tmp = arr.shift();
    arr.push(tmp);
    for (let k = 0; k < arr.length; k++) {
      if (k === 0 || stack.length === 0) {
        if (arr[k] === ")" || arr[k] === "}" || arr[k] === "]") {
          flg = false;
          break;
        }
      }
      if (arr[k] === "(" || arr[k] === "{" || arr[k] === "[") {
        stack.push(arr[k]);
      } else {
        tmp = stack[stack.length - 1];
        if (
          (arr[k] === ")" && tmp === "(") ||
          (arr[k] === "}" && tmp === "{") ||
          (arr[k] === "]" && tmp === "[")
        )
          stack.pop();
        else {
          flg = false;
          break;
        }
      }
    }
    if (flg && stack.length === 0) answer++;
    flg = true;
    stack = [];
  }
  return answer;
}

```

